    'faq' => [
        ['q' => 'Combien coûte une landing page haute conversion ?', 'r' => 'Le tarif de départ est de 150 000 FCFA pour une page complète : structure et textes orientés conversion, design pensé pour le téléphone, formulaire, bouton WhatsApp ou prise de rendez-vous, suivi des conversions avec Google Analytics 4 et le pixel Meta. Le paiement en ligne, le suivi côté serveur, les raccordements à un CRM et les tests A/B sont chiffrés sur devis. Hors zone franc CFA, le prix est établi sur devis.'],
        ['q' => 'Combien de temps faut-il pour créer une landing page ?', 'r' => 'Quelques jours de travail, selon les contenus à préparer et le suivi à installer. Le délai dépend surtout de la rapidité des validations (textes, maquette) et de la disponibilité des preuves : photos, témoignages autorisés, informations sur l\'offre. Prévenez dès le premier échange si la campagne a une date de lancement fixe.'],
        ['q' => 'Quelle différence entre une landing page et un site vitrine ?', 'r' => 'Le site vitrine présente toute votre activité sur plusieurs pages et sert pendant des années. La landing page vise une seule offre, un seul public et une seule action, souvent le temps d\'une campagne ; elle supprime le menu et les liens qui détournent l\'attention. Les deux se complètent : la landing page peut vivre à une adresse de votre site existant.'],
        ['q' => 'Ai-je besoin d\'une landing page si j\'ai déjà un site ?', 'r' => 'Souvent, oui, dès que vous payez de la publicité. Votre page d\'accueil s\'adresse à tous vos publics ; une campagne s\'adresse à un seul public pour une seule offre. Envoyer ce trafic sur l\'accueil oblige le visiteur à chercher l\'offre vue dans l\'annonce, et rend la mesure du coût par prospect beaucoup moins fiable.'],
        ['q' => 'Faut-il un formulaire ou un bouton WhatsApp ?', 'r' => 'Le formulaire convient quand il faut qualifier la demande avant de rappeler, en B2B ou pour un devis. Le bouton WhatsApp convient à un public habitué à écrire depuis son téléphone et à une offre simple, à condition de répondre vite. Le clic WhatsApp se mesure, pas l\'envoi du message : un message prérempli avec un code de campagne compense en partie cette limite.'],
        ['q' => 'Comment savoir combien de prospects la page a rapportés ?', 'r' => 'Par un plan de marquage installé avant le lancement : Google Analytics 4 avec un événement clé comme generate_lead, le pixel Meta avec l\'événement Lead ou CompleteRegistration, des paramètres de campagne sur chaque lien d\'annonce et une page de remerciement mesurée. Pour aller jusqu\'au client, les prospects qualifiés et convertis sont notés dans votre suivi commercial puis remontés dans les outils.'],
        ['q' => 'Faut-il installer l\'API Conversions de Meta en plus du pixel ?', 'r' => 'Meta le recommande dans ses bonnes pratiques : envoyer les mêmes événements par le navigateur et par le serveur, une partie des signaux du navigateur se perdant à cause des bloqueurs, des cookies refusés ou des coupures de connexion. Les deux envois portent le même identifiant d\'événement, et Meta dédoublonne ceux reçus dans un délai de 48 heures. Cette option est chiffrée sur devis.'],
        ['q' => 'Une landing page peut-elle encaisser des paiements par Mobile Money ?', 'r' => 'Oui, en passant par un agrégateur de paiement qui réunit Mobile Money et carte bancaire dans une même fenêtre. Le paiement n\'est compté comme conversion qu\'après confirmation par le prestataire, sur la page de confirmation. Le choix de l\'agrégateur dépend des pays visés et des frais ; le comparatif FedaPay, Kkiapay et CinetPay du site aide à décider.'],
        ['q' => 'Un test A/B est-il utile pour ma page ?', 'r' => 'Il l\'est quand la page reçoit assez de visites pour départager deux versions en quelques semaines. Avec peu de trafic, on teste des différences fortes, comme deux promesses opposées ou formulaire contre WhatsApp, plutôt qu\'une couleur de bouton. Un seul élément change à la fois, l\'indicateur jugé est fixé avant le test, et le test court sur des semaines entières.'],
        ['q' => 'Faut-il un bandeau de cookies sur une landing page ?', 'r' => 'Dès que la page pose des traceurs publicitaires comme le pixel Meta ou la balise Google Ads, oui : la CNIL exige un consentement préalable pour la publicité personnalisée, et refuser doit être aussi simple qu\'accepter. Une mesure d\'audience strictement limitée et anonyme peut en être dispensée sous conditions. Le RGPD s\'applique aussi aux entreprises africaines qui ciblent des personnes situées dans l\'Union.'],
        ['q' => 'Puis-je envoyer des offres aux personnes qui ont rempli le formulaire ?', 'r' => 'Seulement si elles l\'ont accepté. Au Bénin, l\'article 332 du code du numérique interdit la prospection directe par e-mail ou SMS sans consentement préalable, l\'absence de réponse ne valant pas accord. En France, la CNIL demande une case dédiée et non pré-cochée pour les particuliers. Prévoyez cette case sur la page, distincte de l\'envoi de la demande.'],
        ['q' => 'Qui gère les campagnes publicitaires ?', 'r' => 'La prestation porte sur la page, son action et son suivi. Le pilotage quotidien des annonces, des budgets et des ciblages reste chez vous ou chez votre gestionnaire de campagnes. La page est livrée avec les paramètres de campagne, les événements de conversion et les explications nécessaires pour juger chaque annonce sur le coût par prospect et par client.'],
        ['q' => 'Quels moyens de paiement sont acceptés pour la prestation ?', 'r' => 'Le Mobile Money (MTN et Moov), la carte bancaire, PayPal, le virement et les espèces. Les modalités de paiement figurent sur le devis, avant signature.'],
    ],

